class SeatUnavailableError(Exception):
    def __init__(self, seat_id):
        self.seat_id = seat_id
        super().__init__(f"seat {seat_id} is unavailable")

def reserve(seat_id, available):
    if seat_id not in available:
        raise SeatUnavailableError(seat_id)
    available.remove(seat_id)
    return seat_id

seats = {"A1", "A2"}
assert reserve("A1", seats) == "A1"
try:
    reserve("A3", seats)
except SeatUnavailableError as error:
    assert error.seat_id == "A3"
```

```python
class CheckoutError(Exception):
    pass

class OutOfStockError(CheckoutError):
    pass

class PaymentDeclinedError(CheckoutError):
    pass

def response_for(error):
    if isinstance(error, OutOfStockError):
        return "change quantity"
    if isinstance(error, CheckoutError):
        return "checkout failed"
    raise error

assert response_for(OutOfStockError()) == "change quantity"
assert response_for(PaymentDeclinedError()) == "checkout failed"
